INSERT INTO `order_messages` (`id`, `occasion_id`, `message`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, 1, 'From Khabib Nurmagomedov:\r\n\r\n\"Wishing Ali a birthday filled with happiness, health, and unstoppable energy!\"', NULL, '2022-12-06 08:37:35', '2023-10-07 02:52:23'),
(2, 2, 'Hello Yaseen', NULL, '2023-10-03 23:40:03', '2023-10-03 23:40:03'),
(3, 3, 'Hello Ibrahim', NULL, '2023-10-03 23:40:13', '2023-10-03 23:40:13'),
(4, 1, 'From Sojaboy:\r\n\r\n\"Happy Birthday, Abbas! May your day be as vibrant and unique as you are!\"', NULL, '2023-10-06 23:27:27', '2023-10-07 02:51:54'),
(5, 1, '\"To Haider, may your birthday be the start of a fantastic new chapter in your life!\"', NULL, '2023-10-07 02:52:52', '2023-10-07 02:52:52'),
(6, 1, 'From Sayali Paradkar:\r\n\r\n\"Happy Birthday, Khadija! May your day be as beautiful as your spirit.\"', NULL, '2023-10-07 02:53:22', '2023-10-07 02:53:22'),
(7, 1, 'From Mathira:\r\n\r\n\"Hey Palwasha, it\'s your special day! Here\'s to celebrating you and all your awesomeness.\"', NULL, '2023-10-07 02:54:05', '2023-10-07 02:54:05'),
(8, 1, 'From Ayesha Omar:\r\n\r\n\"Wishing Aisha Zulfiqar a birthday filled with love, laughter, and endless joy!\"', NULL, '2023-10-07 02:55:33', '2023-10-07 02:55:33'),
(9, 2, '\"Hey there, Aisha! Your fashion sense is so unique; even Picasso couldn\'t have painted it!\"', NULL, '2023-10-07 02:56:36', '2023-10-07 02:56:36'),
(10, 2, 'From Khabib Nurmagomedov:\r\n\r\n\"Firdous, your resilience is impressive, but I bet you\'d tap out in a thumb-wrestling match with me!\"', NULL, '2023-10-07 02:57:10', '2023-10-07 02:57:10'),
(11, 2, 'From Urvashi Dholakia:\r\n\r\n\"To Niman, you\'re like a fine wine - you get better with age... or maybe it\'s just the wine talking!\"', NULL, '2023-10-07 02:57:54', '2023-10-07 02:57:54'),
(12, 2, 'From Sayali Paradkar:\r\n\r\n\"Zoya, you\'re one of a kind - like a limited edition collector\'s item, but with more quirks!\"', NULL, '2023-10-07 02:58:27', '2023-10-07 02:58:27'),
(13, 2, 'From Mathira:\r\n\r\n\"Oh, Bareera, you\'re a true enigma! It\'s impossible to predict what you\'ll do next.\"', NULL, '2023-10-07 02:58:57', '2023-10-07 02:58:57'),
(14, 2, 'From Ayesha Omar:\r\n\r\n\"Hey Safa, your sense of humor is so rare; it\'s like finding a unicorn at a petting zoo!\"', NULL, '2023-10-07 02:59:26', '2023-10-07 02:59:26'),
(15, 3, 'From Sojaboy:\r\n\r\n\"Hey Ali jee, let\'s chat and spill the tea on all the latest gossip!\"', NULL, '2023-10-07 03:00:04', '2023-10-07 03:00:04'),
(16, 3, 'From Khabib Nurmagomedov:\r\n\r\n\"Zulqarnain, it\'s time for a virtual chat session! Tell me, what\'s on your mind?\"', NULL, '2023-10-07 03:00:43', '2023-10-07 03:00:43'),
(17, 3, 'From Urvashi Dholakia:\r\n\r\n\"To Fatima, grab your virtual coffee, and let\'s have a chat about life\'s ups and downs!\"', NULL, '2023-10-07 03:01:10', '2023-10-07 03:01:10'),
(18, 3, 'From Sayali Paradkar:\r\n\r\n\"Javeria conversation? Let\'s chat and share stories.\"', NULL, '2023-10-07 03:01:41', '2023-10-07 03:01:41'),
(19, 3, 'From Mathira:\r\n\r\n\"Hey there, Zainab, fancy a chat filled with laughter and positivity?\"', NULL, '2023-10-07 03:02:11', '2023-10-07 03:02:11'),
(20, 3, 'From Ayesha Omar:\r\n\r\n\"Time to chat, Kulsoom! What\'s been going on in your world lately?\"', NULL, '2023-10-07 03:02:50', '2023-10-07 03:02:50'),
(21, 1, 'From Mathira: hello everyone', '2023-11-08 16:54:44', '2023-11-08 16:54:32', '2023-11-08 16:54:44');
